from dataclasses import asdict, dataclass, replace
from datetime import datetime
from gzip import decompress
from hashlib import sha256
from io import BytesIO
import json
from pathlib import Path
import signal

import numpy as np
import pandas as pd
from pandas.tseries import holiday
from scipy.optimize import minimize
import yaml


TRADING_DAYS = 252


class NyseHolidays(holiday.AbstractHolidayCalendar):
    rules = [
        holiday.Holiday("New Year's Day", month=1, day=1, observance=holiday.sunday_to_monday),
        holiday.USMartinLutherKingJr,
        holiday.USPresidentsDay,
        holiday.GoodFriday,
        holiday.USMemorialDay,
        holiday.Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01",
                        observance=holiday.nearest_workday),
        holiday.Holiday("Independence Day", month=7, day=4, observance=holiday.nearest_workday),
        holiday.USLaborDay,
        holiday.USThanksgivingDay,
        holiday.Holiday("Christmas Day", month=12, day=25, observance=holiday.nearest_workday),
    ]


def market_sessions(start, end):
    if start.year < 2010 or end.year > 2025:
        raise ValueError("NYSE calendar closure dates cover 2010 through 2025.")
    holidays = NyseHolidays().holidays(start, end)
    closures = pd.to_datetime([
        "2012-10-29", "2012-10-30",  # Hurricane Sandy
        "2018-12-05", "2025-01-09",  # National days of mourning
    ])
    return pd.bdate_range(start, end).difference(holidays.union(closures))


@dataclass(frozen=True)
class Parameters:
    lookback_sessions: int
    liquidity_sessions: int
    liquidity_top_n: int
    cardinality: int
    risk_aversion: float
    min_weight: float
    max_weight: float
    lag_sessions: int
    transaction_cost_bps: float
    slippage_bps: float
    cash_buffer_bps: float

    @property
    def friction(self):
        return (self.transaction_cost_bps + self.slippage_bps) / 10_000

    @property
    def cash_buffer(self):
        return self.cash_buffer_bps / 10_000

    def validate(self, universe_size):
        if self.lag_sessions < 1 or self.lookback_sessions < 2 or self.liquidity_sessions < 1:
            raise ValueError("Use a positive execution lag and valid estimation windows.")
        if not 1 <= self.cardinality <= self.liquidity_top_n <= universe_size:
            raise ValueError("Invalid cardinality or liquidity shortlist size.")
        equal_weight = 1 / self.cardinality
        if not 0 < self.min_weight <= equal_weight <= self.max_weight <= 1:
            raise ValueError("Weight bounds are incompatible with full investment.")
        if not (self.risk_aversion > 0 and self.transaction_cost_bps >= 0
                and self.slippage_bps >= 0 and self.friction < 1):
            raise ValueError("Use positive risk aversion and nonnegative friction below 100%.")
        if not 0 < self.cash_buffer < 1:
            raise ValueError("Use a positive cash buffer below 100%.")


def load_config(config_path="config.yaml"):
    with open(config_path, "rb") as file:
        raw = file.read()
    return yaml.safe_load(raw), raw


def load_panel(universe, benchmark, risk_free, start, end, *, first_trade_dates=None, config=None, config_path="config.yaml"):
    sessions = market_sessions(start, end)
    tickers = [*universe, benchmark, risk_free]
    data = (config or {}).get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the Yahoo Finance snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = snapshot.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    fetched_at = header.decode("utf-8").strip()
    datetime.fromisoformat(fetched_at)
    input_digest = sha256(body).hexdigest()
    with BytesIO(snapshot) as source:
        source.readline()
        panel = pd.read_csv(source, header=[0, 1], index_col=0, parse_dates=True)
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: Yahoo Finance snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); yfinance Adj Close total-return (splits and distributions). "
        "The script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    print(f"Price sessions: {len(panel)} ({panel.index[0].date()} to {panel.index[-1].date()})")

    adjusted = panel["adjusted_close"].reindex(columns=tickers)
    adjusted = adjusted.where((adjusted > 0) & np.isfinite(adjusted))
    liquidity = panel["dollar_volume"].reindex(columns=universe)
    liquidity = liquidity.where((liquidity > 0) & np.isfinite(liquidity))
    if not adjusted.index.is_unique:
        raise ValueError("Duplicate dates in Yahoo Finance prices.")
    observed = adjusted.index[adjusted.notna().any(axis=1)]
    unexpected = observed.difference(sessions)
    if len(unexpected):
        dates = unexpected.strftime("%Y-%m-%d").tolist()
        raise ValueError(f"Yahoo Finance reported quotes outside the NYSE calendar: {dates}.")
    adjusted = adjusted.reindex(sessions)
    missing = sessions[adjusted[[benchmark, risk_free]].isna().any(axis=1)]
    if len(missing):
        dates = missing.strftime("%Y-%m-%d").tolist()
        raise ValueError(f"Missing {benchmark} or {risk_free} prices on NYSE sessions: {dates}.")

    liquidity = liquidity.reindex(sessions)
    for ticker, first_trade in (first_trade_dates or {}).items():
        if ticker not in universe:
            raise ValueError(f"Listing cutoff configured for unknown stock {ticker}.")
        before_listing = sessions < pd.Timestamp(first_trade)
        adjusted.loc[before_listing, ticker] = np.nan
        liquidity.loc[before_listing, ticker] = np.nan
    usable = (adjusted[universe].notna() & liquidity.notna()).any(axis=0)
    if not usable.all():
        symbols = ", ".join(usable.index[~usable])
        raise ValueError(f"No session with both price and liquidity for configured stocks: {symbols}.")

    return adjusted, liquidity, fetched_at


def fit_weights(history, params, date):
    expected = history.mean(axis=0) * TRADING_DAYS
    covariance = np.atleast_2d(np.cov(history, rowvar=False, ddof=1)) * TRADING_DAYS
    risk_matrix = covariance * params.risk_aversion

    def objective(weights):
        return 0.5 * weights @ risk_matrix @ weights - expected @ weights

    def gradient(weights):
        return risk_matrix @ weights - expected

    equal = np.full(params.cardinality, 1 / params.cardinality)
    result = minimize(
        objective, equal, jac=gradient, method="SLSQP",
        bounds=[(params.min_weight, params.max_weight)] * params.cardinality,
        constraints={"type": "eq", "fun": lambda weights: weights.sum() - 1,
                     "jac": lambda weights: np.ones_like(weights)},
        options={"ftol": 1e-11, "maxiter": 200},
    )
    weights = result.x
    if (not result.success or not np.isfinite(weights).all()
            or abs(weights.sum() - 1) > 1e-8
            or weights.min() < params.min_weight - 1e-8
            or weights.max() > params.max_weight + 1e-8):
        raise RuntimeError(f"{date.date()} mean-variance optimization failed: {result.message}")
    return weights


def monthly_targets(prices, dollar_volume, proxy_returns, start, params):
    stock_returns = prices.pct_change(fill_method=None)
    liquidity = dollar_volume.rolling(params.liquidity_sessions).median()
    dates = stock_returns.index
    months = dates.to_period("M")
    month_ends = np.flatnonzero(months[:-1] != months[1:])
    targets = {}
    for row in month_ends:
        execution = row + params.lag_sessions
        if execution >= len(dates) or dates[execution] < start:
            continue
        date = dates[row]
        first = row - params.lookback_sessions + 1
        if first < 1:
            raise ValueError(f"Download more warm-up history before {date.date()}.")

        history = stock_returns.iloc[first:row + 1].dropna(axis=1)
        liquid = (liquidity.iloc[row].reindex(history.columns).dropna()
                  .nlargest(params.liquidity_top_n).index)
        excess = history[liquid].sub(proxy_returns.iloc[first:row + 1], axis=0)
        volatility = excess.std(ddof=1)
        scores = excess.mean().div(volatility.where(volatility > 0)).dropna()
        selected = scores.nlargest(params.cardinality).index
        if len(selected) < params.cardinality:
            continue

        target = np.zeros(prices.shape[1])
        target[prices.columns.get_indexer(selected)] = fit_weights(
            history[selected].to_numpy(), params, date,
        )
        targets[execution] = target
    return targets


def size_orders(positions, cash, previous_close, target, friction, cash_buffer):
    """Lock share changes using only the preceding close and available positions."""
    can_size = np.isfinite(previous_close)
    missing_sizes = np.count_nonzero(~can_size & ((positions > 0) | (target > 0)))
    quotes = previous_close[can_size]
    # A stale position is still marked in returns but cannot fund orders.
    available_value = cash + float(positions[can_size] @ quotes)
    reserve = available_value * cash_buffer

    changes = np.zeros_like(positions)
    changes[can_size] = (available_value - reserve) * target[can_size] / quotes - positions[can_size]
    sales = np.minimum(changes, 0.0)
    buys = np.maximum(changes, 0.0)
    estimated_proceeds = -float(sales[can_size] @ quotes) * (1 - friction)
    budget = max(cash + estimated_proceeds - reserve, 0.0)
    estimated_cost = float(buys[can_size] @ quotes) * (1 + friction)
    if estimated_cost > budget:
        buys *= budget / estimated_cost
    return sales + buys, missing_sizes


def fill_orders(positions, cash, quantities, close, friction, date):
    """Apply the locked quantities where a closing quote exists, or reject the fill."""
    can_fill = np.isfinite(close)
    quotes = close[can_fill]
    filled = quantities[can_fill]
    missing_fills = np.count_nonzero(quantities[~can_fill])
    sell_notional = -float(np.minimum(filled, 0.0) @ quotes)
    buy_notional = float(np.maximum(filled, 0.0) @ quotes)
    net_sales = sell_notional * (1 - friction)
    gross_purchases = buy_notional * (1 + friction)
    cash_after = cash + net_sales - gross_purchases
    if cash_after < 0:
        raise RuntimeError(
            f"{date}: locked quantities require negative cash ({cash_after:.8g}); "
            f"starting cash={cash:.8g}, net sales={net_sales:.8g}, "
            f"purchases including costs={gross_purchases:.8g}, missing fills={missing_fills}."
        )

    updated = positions.copy()
    updated[can_fill] += filled
    trade_count = np.count_nonzero(updated != positions)
    return updated, cash_after, sell_notional + buy_notional, trade_count, missing_fills


def simulate(prices, targets, start, friction, cash_buffer, max_stale_sessions):
    """Carry fixed quantities from the sizing session into the next close."""
    first_row = prices.index.searchsorted(start)
    close_prices = prices.to_numpy()
    marked_prices = prices.ffill().fillna(0.0).to_numpy()
    positions = np.zeros(prices.shape[1])
    stale_sessions = np.zeros(prices.shape[1], dtype=int)
    cash = previous_value = 1.0
    records = []
    order_plan = None
    if first_row < len(prices) and first_row in targets:
        if first_row == 0:
            raise ValueError("First scheduled fill requires a preceding sizing session.")
        order_plan = size_orders(
            positions, cash, close_prices[first_row - 1], targets[first_row], friction, cash_buffer,
        )

    for row in range(first_row, len(prices)):
        date = prices.index[row].date()
        close = close_prices[row]
        stale = (positions > 0) & ~np.isfinite(close)
        stale_sessions[~stale] = 0
        stale_sessions[stale] += 1
        overdue = stale_sessions > max_stale_sessions
        if overdue.any():
            symbols = ", ".join(prices.columns[overdue])
            raise RuntimeError(f"{date}: missing held-stock prices for more than "
                               f"{max_stale_sessions} sessions: {symbols}.")

        marks = marked_prices[row]
        value_before = cash + float(positions @ marks)
        traded = 0.0
        trade_count = missing_sizes = missing_fills = 0
        if order_plan is not None:
            quantities, missing_sizes = order_plan
            positions, cash, traded, trade_count, missing_fills = fill_orders(
                positions, cash, quantities, close, friction, date,
            )
        value_after = cash + float(positions @ marks)
        records.append((
            value_after / previous_value - 1, traded / value_before, trade_count,
            cash / value_after, traded * friction, missing_sizes, missing_fills,
            np.count_nonzero(stale),
        ))
        previous_value = value_after

        next_row = row + 1
        order_plan = None
        if next_row < len(prices) and next_row in targets:
            order_plan = size_orders(positions, cash, close, targets[next_row], friction, cash_buffer)
    return pd.DataFrame(
        records, columns=["return", "turnover", "n_trades", "cash_weight",
                          "friction_paid", "missing_sizes", "missing_fills", "stale_position_days"],
        index=prices.index[first_row:],
    )


def period_metrics(daily_results, proxy_returns):
    returns = daily_results["return"].to_numpy()
    if not len(returns):
        return dict(cagr=None, ann_vol=None, sharpe=None, sharpe_excess=None, max_drawdown=None,
                    total_return=None, turnover=0.0, n_trades=0)
    growth_curve = np.cumprod(1 + returns)
    peaks = np.maximum.accumulate(np.r_[1.0, growth_curve])[1:]
    volatility = returns.std(ddof=1) if len(returns) > 1 else None
    excess = returns - proxy_returns.reindex(daily_results.index).to_numpy()
    excess_volatility = excess.std(ddof=1) if len(returns) > 1 else None
    annualizer = np.sqrt(TRADING_DAYS)
    return {
        "cagr": float(growth_curve[-1] ** (TRADING_DAYS / len(returns)) - 1),
        "ann_vol": float(volatility * annualizer) if volatility is not None else None,
        "sharpe": float(returns.mean() / volatility * annualizer) if volatility else None,
        "sharpe_excess": (
            float(excess.mean() / excess_volatility * annualizer)
            if excess_volatility is not None and np.isfinite(excess_volatility)
            and excess_volatility > 0 else None
        ),
        "max_drawdown": float((growth_curve / peaks - 1).min()),
        "total_return": float(growth_curve[-1] - 1),
        "turnover": float(daily_results["turnover"].sum()),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def run_strategy(prices, dollar_volume, proxy_returns, start, params, max_stale_sessions):
    targets = monthly_targets(prices, dollar_volume, proxy_returns, start, params)
    return simulate(prices, targets, start, params.friction, params.cash_buffer, max_stale_sessions)


def summarize(daily_results, proxy_returns, is_end):
    periods = {
        "is": daily_results.loc[:is_end],
        "oos": daily_results.loc[daily_results.index > is_end],
        "full": daily_results,
    }
    return {name: period_metrics(period, proxy_returns) for name, period in periods.items()}


def main():
    config, _ = load_config()
    universe = config["universe"]
    benchmark, risk_free = config["benchmark"], config["risk_free_proxy"]
    if len(set([*universe, benchmark, risk_free])) != len(universe) + 2:
        raise ValueError("Stock, benchmark and risk-free symbols must be distinct.")
    data_start, start, is_end, end = (
        pd.Timestamp(config[name]) for name in ("data_start", "backtest_start", "is_end", "end")
    )
    if not data_start < start < is_end < end:
        raise ValueError("Expected data_start < backtest_start < is_end < end.")
    max_stale_sessions = config["max_stale_sessions"]
    if type(max_stale_sessions) is not int or max_stale_sessions < 0:
        raise ValueError("max_stale_sessions must be a nonnegative integer.")
    official = Parameters(**config["parameters"])
    cases = {
        name: replace(official, **overrides) for name, overrides in config["robustness"].items()
    }
    combinations = {official, *cases.values()}
    if len(combinations) != 1 + len(cases):
        raise ValueError("Each robustness case must specify a distinct parameter combination.")
    for params in combinations:
        params.validate(len(universe))

    adjusted, liquidity, fetched_at = load_panel(
        universe, benchmark, risk_free, data_start, end,
        first_trade_dates=config.get("first_trade_dates"),
        config=config,
    )
    stocks = adjusted[universe]
    proxy_returns = adjusted[risk_free].pct_change(fill_method=None)
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance Adj Close total-return (splits and distributions) "
          "(label of the snapshot's adjustment convention; the run itself does not call yfinance)")
    print("ROBUSTNESS (IS ONLY)")
    for name, params in cases.items():
        daily_results = run_strategy(
            stocks.loc[:is_end], liquidity.loc[:is_end], proxy_returns.loc[:is_end], start, params,
            max_stale_sessions,
        )
        metrics = period_metrics(daily_results, proxy_returns.loc[:is_end])
        print(f"  {name} {json.dumps(config['robustness'][name])} {json.dumps(metrics, allow_nan=False)}")

    daily_results = run_strategy(stocks, liquidity, proxy_returns, start, official, max_stale_sessions)
    if daily_results.empty:
        raise ValueError("Backtest date range contains no market sessions.")
    index_results = simulate(
        adjusted[[benchmark]], {adjusted.index.searchsorted(start): np.ones(1)},
        start, official.friction, official.cash_buffer, max_stale_sessions,
    )
    strategy_metrics = summarize(daily_results, proxy_returns, is_end)
    benchmark_metrics = summarize(index_results, proxy_returns, is_end)
    data_range = {
        "start": daily_results.index[0].date().isoformat(),
        "end": daily_results.index[-1].date().isoformat(),
    }
    print(f"Date Range: {data_range['start']} to {data_range['end']}")
    print(f"OFFICIAL_PARAMETERS: {json.dumps(asdict(official))}")
    diagnostics = {}
    for name, frame in (("strategy", daily_results), (benchmark, index_results)):
        cash_on_fill_days = frame.loc[frame["n_trades"] > 0, "cash_weight"]
        diagnostics[name] = {
            "min_close_cash_weight": float(frame["cash_weight"].min()),
            "min_fill_cash_weight": float(cash_on_fill_days.min()) if len(cash_on_fill_days) else None,
            "friction_paid_per_initial_value": float(frame["friction_paid"].sum()),
            "missing_sizes": int(frame["missing_sizes"].sum()),
            "missing_fills": int(frame["missing_fills"].sum()),
            "stale_position_days": int(frame["stale_position_days"].sum()),
        }
    print(f"EXECUTION_DIAGNOSTICS: {json.dumps(diagnostics, allow_nan=False)}")
    for period in ("is", "oos", "full"):
        print(f"{period.upper()} strategy: {json.dumps(strategy_metrics[period], allow_nan=False)}")
        print(f"{period.upper()} {benchmark}: {json.dumps(benchmark_metrics[period], allow_nan=False)}")
    print(f"PARAM_COMBOS_TRIED: {len(combinations)}")
    results = {
        "strategy": config["strategy"],
        "data_range": data_range,
        **strategy_metrics,
        "benchmark": {"ticker": benchmark, **benchmark_metrics},
    }
    print("RESULTS_JSON: " + json.dumps(results, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(9 * 60)
    try:
        main()
    finally:
        signal.alarm(0)
